CREATE COLUMN TABLE "TEST_AP"."OSPP" ("ItemCode" NVARCHAR(50) NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Discount" DECIMAL(21,6) CS_FIXED, "ListNum" SMALLINT CS_INT DEFAULT 0, "AutoUpdt" NVARCHAR(1) DEFAULT 'Y', "EXPAND" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "SrcPrice" SMALLINT CS_INT DEFAULT 0, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UpdateDate" LONGDATE CS_LONGDATE, "Valid" NVARCHAR(1) DEFAULT 'Y', "ValidFrom" LONGDATE CS_LONGDATE, "ValidTo" LONGDATE CS_LONGDATE, PRIMARY KEY ("CardCode", "ItemCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "OSPP_CARD" ON "TEST_AP"."OSPP" ( "CardCode" ASC );
CREATE INDEX "OSPP_ITEM" ON "TEST_AP"."OSPP" ( "ItemCode" ASC );
CREATE INDEX "OSPP_CURRENCY" ON "TEST_AP"."OSPP" ( "Currency" ASC )